//! Bit-exact conformance of `neuro_core::peerkey` against the Python reference (`unsw_to_d1.py`).
//! `peerkey.txt` is generated by `tools/neuro-research/gen_peerkey_golden.py`; see it for the line format.

use neuro_core::peerkey::*;

fn ip_of(h: &str) -> Ip {
    let b: Vec<u8> = (0..h.len()).step_by(2).map(|i| u8::from_str_radix(&h[i..i + 2], 16).unwrap()).collect();
    match b.len() {
        4 => Ip::V4([b[0], b[1], b[2], b[3]]),
        16 => {
            let mut a = [0u8; 16];
            a.copy_from_slice(&b);
            Ip::V6(a)
        }
        n => panic!("bad address length {n}"),
    }
}

fn opt64(s: &str) -> Option<u64> {
    if s == "-" { None } else { Some(u64::from_str_radix(s, 16).unwrap()) }
}

#[test]
fn peerkey_golden() {
    let text = include_str!("peerkey.txt");
    let mut table: NameTable<64> = NameTable::new();
    let (mut keys, mut ops) = (0usize, 0usize);
    for (ln, line) in text.lines().enumerate() {
        let t: Vec<&str> = line.split_whitespace().collect();
        match t.first() {
            Some(&"P") => {
                let mode = match t[1] {
                    "exact" => Mode::Exact,
                    "v1-24" => Mode::V1 { plen: 24 },
                    "v1-16" => Mode::V1 { plen: 16 },
                    "v2-24" => Mode::V2 { plen: 24 },
                    "v2-16" => Mode::V2 { plen: 16 },
                    m => panic!("mode {m}"),
                };
                let proto = match t[2] {
                    "tcp" => Proto::Tcp,
                    "udp" => Proto::Udp,
                    _ => Proto::Any,
                };
                let (fp, rule) = peer_fp(mode, &ip_of(t[3]), t[4].parse().unwrap(), proto, opt64(t[5]));
                let want_rule = match t[7] {
                    "exact" => Rule::Exact,
                    "class" => Rule::Class,
                    "local" => Rule::Local,
                    "named" => Rule::Named,
                    _ => Rule::Prefix,
                };
                assert_eq!(fp, u32::from_str_radix(t[6], 16).unwrap(), "line {}: fingerprint", ln + 1);
                assert_eq!(rule, want_rule, "line {}: rule", ln + 1);
                keys += 1;
            }
            Some(&"I") => {
                table.insert(t[1].parse().unwrap(), &ip_of(t[2]), u64::from_str_radix(t[3], 16).unwrap(), t[4].parse().unwrap());
                ops += 1;
            }
            Some(&"L") => {
                let got = table.lookup(t[1].parse().unwrap(), &ip_of(t[2]), t[3].parse().unwrap());
                assert_eq!(got, opt64(t[4]), "line {}: lookup", ln + 1);
                ops += 1;
            }
            _ => {}
        }
    }
    assert!(keys >= 3000 && ops == 4000, "vector file incomplete: {keys} keys, {ops} table ops");
    println!(
        "peerkey: {keys} keys bit-exact, {ops} name-table ops identical; NameEntry = {} B, NameTable<4096> = {} KiB",
        core::mem::size_of::<NameEntry>(),
        core::mem::size_of::<NameTable<4096>>() / 1024
    );
}

#[test]
fn svc_state_matches_string_form() {
    // "svc:vendor.com:443" in one go == state after "svc:vendor.com:" continued with "443"
    let whole = Fnv::new().bytes(b"svc:vendor.com:443").fp();
    assert_eq!(Fnv(svc_state(b"vendor.com")).dec(443).fp(), whole);
    assert_eq!(Fnv::new().dec(0).0, Fnv::new().bytes(b"0").0);
    assert_eq!(Fnv::new().dec(65535).0, Fnv::new().bytes(b"65535").0);
    assert_eq!(Fnv::new().hex(&[0x0a, 0xff]).0, Fnv::new().bytes(b"0aff").0);
}
